-- Aggregate only. No customer/provider identifiers, tokens or content.
BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout='10s';
SELECT jsonb_build_object('observed_at',now(),'provider_events',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select status as state,count(*) as count,min(received_at) as oldest,max(attempts) as max_attempts from public.provider_events group by status) x),'payment_captures',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select status as state,count(*) as count,min(received_at) as oldest from public.payment_captures group by status) x),'payment_compensations',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select status as state,count(*) as count,min(created_at) as oldest,max(attempts) as max_attempts from public.payment_compensations group by status) x),'payment_jobs',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select status as state,count(*) as count,min(created_at) as oldest,max(attempts) as max_attempts from public.payment_jobs group by status) x),'play_payment_jobs',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select status as state,count(*) as count,min(created_at) as oldest,max(attempts) as max_attempts from public.play_payment_jobs group by status) x),'ucb_external_refunds',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select status as state,count(*) as count,min(created_at) as oldest,max(attempts) as max_attempts from public.ucb_external_refunds group by status) x),'play_price_sync',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select status as state,count(*) as count,min(updated_at) as oldest,max(attempts) as max_attempts from public.play_price_sync group by status) x),'notes_choice_checkouts',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select state as state,count(*) as count,min(created_at) as oldest from public.notes_choice_checkouts group by state) x),'note_pdf_validation_jobs',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select status as state,count(*) as count,min(updated_at) as oldest,max(attempts) as max_attempts from public.note_pdf_validation_jobs group by status) x),'note_upload_requests',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select status as state,count(*) as count,min(created_at) as oldest from public.note_upload_requests group by status) x),'payment_deadlines',(select jsonb_build_object('overdue',count(*) filter(where status not in ('done','parked') and deadline_at<now()),'parked',count(*) filter(where status='parked'),'expired_leases',count(*) filter(where status='processing' and lease_until<now())) from public.payment_jobs),'provider_unlinked',(select count(*) from public.provider_events e where status in ('pending','parked') and not exists(select 1 from public.orders o where o.razorpay_payment_id=e.payment_id)),'void_tokens',(select count(*) from public.play_void_tokens),'void_sweep_last_update',(select max(updated_at) from public.play_void_sweep_state),'recovery_cursor_last_update',(select max(updated_at) from public.play_recovery_cursor),'expired_wallet_reservations',(select count(*) from public.wallet_order_reservations where expires_at<now()),'discount_reservations',(select count(*) from public.first_discount_reservations),'external_reports_due',(select count(*) from public.orders where external_transaction_token is not null and external_report_status in ('pending','failed')),'play_consumption_due',(select count(*) from public.orders where provider='play' and status='paid' and play_consumption_status in ('pending','failed')),'review_flags',(select jsonb_object_agg(reason,n) from (select reason,count(*) n from public.order_review_flags group by reason)x)) AS queues;
ROLLBACK;
